<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {useWorkbench} from '../stores/workbench'
import {uid,type Model} from '../lib/domain'
import Dialog from '../components/Dialog.vue'
import Icon from '../components/Icon.vue'
import ModelDefaultSelect from '../components/ModelDefaultSelect.vue'
const store=useWorkbench(),open=ref(false),query=ref(''),capFilter=ref(''),params=ref('{\n  "temperature": 0.6\n}'),editing=ref('')
const blank=()=>({id:uid('model'),name:'',provider:'',protocol:'CHAT_COMPLETIONS_COMPATIBLE',baseUrl:'',remoteModelId:'',credentialRef:'CREATOR_MODEL_KEY',capabilities:['TEXT_REASONING'],parameters:{},enabled:false,verified:false})
const form=reactive<Model>(blank());const protocols=['CHAT_COMPLETIONS_COMPATIBLE','RESPONSES','ANTHROPIC_MESSAGES','GEMINI_GENERATE_CONTENT','CUSTOM_HTTP','LOCAL_GATEWAY']
const filtered=computed(()=>store.state.models.filter(m=>(m.name+m.provider+m.remoteModelId).toLowerCase().includes(query.value.toLowerCase())&&(!capFilter.value||m.capabilities.includes(capFilter.value))))
function edit(m?:Model){Object.assign(form,m?JSON.parse(JSON.stringify(m)):blank());editing.value=m?.id??'';params.value=JSON.stringify(form.parameters??{},null,2);open.value=true}
async function save(){try{const parameters=JSON.parse(params.value);if(!parameters||Array.isArray(parameters)||typeof parameters!=='object')throw new Error('参数必须是 JSON 对象');if(await store.command({type:'SAVE_MODEL',payload:{model:{...form,parameters}}},'模型档案已保存；接入与能力验证尚未执行'))open.value=false}catch(e){store.toast(e instanceof Error?e.message:'参数格式错误','error')}}
</script>
<template><div class="page-content"><div class="page-heading"><div><span class="page-eyebrow">选择适合每一步的能力</span><h1>你的模型团队<span class="heading-dot">.</span></h1><p>一个工作台，连接不同服务商。让合适的模型，做擅长的事。</p></div><button class="btn primary" @click="edit()"><Icon name="Plus"/>登记模型</button></div><div class="model-summary-strip"><span><Icon name="Boxes"/>{{store.state.models.length}} 个已登记模型</span><span><Icon name="Shapes"/>25 类可选能力</span><span><Icon name="GitBranch"/>4 级配置继承</span><span class="muted">登记不等于已连接，调用与能力测试将在后续接入</span></div><div class="filter-bar"><div class="inline-search wide"><Icon name="Search" :size="16"/><input v-model="query" placeholder="搜索模型、服务商或模型 ID" aria-label="搜索模型"></div><select v-model="capFilter" class="filter-select" aria-label="按能力筛选"><option value="">全部模型能力</option><option v-for="c in store.catalog.capabilities" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div class="model-table" v-if="filtered.length"><div class="model-table-header"><span>模型 / 服务商</span><span>能力</span><span>协议与状态</span><span/></div><div v-for="m in filtered" :key="m.id" class="model-table-row"><div class="model-name-cell"><span class="model-avatar"><Icon name="Boxes" :size="21"/></span><div><b>{{m.name}}</b><small>{{m.provider||'自定义服务商'}} · {{m.remoteModelId}}</small></div></div><div class="capability-tags"><span v-for="c in m.capabilities.slice(0,3)" :key="c">{{store.catalog.capabilities.find(x=>x.id===c)?.name}}</span><span v-if="m.capabilities.length>3">+{{m.capabilities.length-3}}</span></div><div><small class="protocol-label">{{m.protocol}}</small><span class="badge neutral">待接入验证</span></div><button class="icon-btn" :aria-label="'编辑'+m.name" @click="edit(m)"><Icon name="Pencil" :size="16"/></button></div></div><div v-else class="empty-state model-empty"><span class="empty-orbit"><Icon name="Boxes" :size="34"/></span><h2>{{query||capFilter?'没有匹配的模型':'把你的第一个模型，带进工作台'}}</h2><p>支持自定义服务地址、真实模型 ID、协议、能力和参数预设。<br>真实密钥由后端环境变量提供，不写入浏览器配置。</p><button class="btn primary" @click="edit()"><Icon name="Plus" :size="16"/>登记一个模型</button></div><section class="bindings-section"><div class="global-default-panel"><ModelDefaultSelect scope="GLOBAL" label="全局默认模型"/><p>下方能力默认可覆盖全局模型。不支持的能力需要另选模型，未配置时不会强行使用语言模型执行 TTS 或视频生成。</p></div><div class="section-heading"><div><h2>全局能力默认</h2><p>节点覆盖 → 项目覆盖 → Agent 默认 → 全局默认。</p></div><Icon name="GitBranch" :size="24"/></div><div class="binding-grid"><label v-for="cap in store.catalog.capabilities.map(c=>c.id)" :key="cap">{{store.catalog.capabilities.find(c=>c.id===cap)?.name}}<select :value="store.state.globalBindings[cap]??''" @change="store.command({type:'SET_BINDING',payload:{scope:'GLOBAL',capability:cap,modelId:($event.target as HTMLSelectElement).value}},'全局默认已保存')"><option value="">继承全局模型（需支持此能力）</option><option v-for="m in store.state.models.filter(m=>m.capabilities.includes(cap))" :key="m.id" :value="m.id">{{m.name}}</option></select></label></div></section><Dialog :open="open" :title="editing?'编辑模型档案':'登记你的模型'" wide @close="open=false"><form class="form-stack" @submit.prevent="save"><div class="form-row"><label>显示名称<input v-model="form.name" required placeholder="例如：我的写作模型" maxlength="80"></label><label>服务商<input v-model="form.provider" placeholder="自定义服务商" maxlength="80"></label></div><div class="form-row"><label>协议<select v-model="form.protocol"><option v-for="p in protocols" :key="p">{{p}}</option></select></label><label>真实模型 ID<input v-model="form.remoteModelId" required placeholder="填写供应商提供的模型标识"></label></div><label>服务地址<input v-model="form.baseUrl" type="url" required placeholder="https://your-provider.example/v1"></label><label>认证环境变量名称<input v-model="form.credentialRef" required pattern="[A-Z][A-Z0-9_]*" placeholder="CREATOR_MODEL_KEY"><small>这里只填变量名，请勿粘贴 API Key。当前版本不读取或发送认证信息。</small></label><fieldset class="capability-picker"><legend>模型能力</legend><label v-for="c in store.catalog.capabilities" :key="c.id" class="checkbox-label"><input type="checkbox" :value="c.id" v-model="form.capabilities">{{c.name}}</label></fieldset><label>参数预设（JSON）<textarea class="code-input" v-model="params" rows="5" spellcheck="false"/><small>真实调用前需按模型协议核对参数映射；当前仅保存档案。</small></label><div class="dialog-actions"><button type="button" class="btn danger-text" v-if="editing" @click="store.command({type:'DELETE_MODEL',payload:{id:editing}},'模型档案已移除，相关绑定已清理').then(ok=>{if(ok)open=false})"><Icon name="Trash2" :size="15"/>移除档案</button><button class="btn primary" :disabled="store.saving"><Icon name="Save" :size="16"/>保存模型</button></div></form></Dialog></div></template>
